{"content": "1|//! pesti-server v2: Enhanced OpenAI-compatible HTTP server with model management.
2|//!
3|//! Features:
4|//! - Model hot-swapping (load/unload via API)
5|//! - Connection pooling with concurrent request handling
6|//! - SSE streaming for chat completions
7|//! - Hardware-aware auto-tuning integration
8|
9|use axum::extract::{Json, State};
10|use axum::http::StatusCode;
11|use axum::response::{IntoResponse, Sse};
12|use axum::response::sse::Event;
13|use axum::routing::{get, post};
14|use axum::Router;
15|use chrono::Utc;
16|use pesti_runner::llama::{LlamaChatMessage, LlamaRunner, SamplingConfig};
17|use std::ffi::CString;
18|use serde::{Deserialize, Serialize};
19|use std::net::SocketAddr;
20|use std::sync::Arc;
21|use tokio::sync::{Mutex, RwLock};
22|use tokio_stream::StreamExt;
23|use tracing_subscriber::{EnvFilter, fmt};
24|use uuid::Uuid;
25|
26|// ── OpenAI API types ────────────────────────────────────────────────
27|
28|#[derive(Debug, Deserialize)]
29|struct ChatCompletionRequest {
30|    model: String,
31|    messages: Vec<ChatMessage>,
32|    #[serde(default = "default_temperature")]
33|    temperature: f64,
34|    #[serde(default = "default_top_p")]
35|    top_p: f64,
36|    #[serde(default = "default_max_tokens")]
37|    max_tokens: u32,
38|    #[serde(default)]
39|    stream: bool,
40|}
41|
42|#[derive(Debug, Deserialize, Serialize, Clone)]
43|struct ChatMessage {
44|    role: String,
45|    content: String,
46|}
47|
48|fn default_temperature() -> f64 { 0.7 }
49|fn default_top_p() -> f64 { 1.0 }
50|fn default_max_tokens() -> u32 { 512 }
51|
52|#[derive(Debug, Serialize)]
53|struct ChatCompletionResponse {
54|    id: String,
55|    object: String,
56|    created: i64,
57|    model: String,
58|    choices: Vec<ChatChoice>,
59|    usage: Usage,
60|}
61|
62|#[derive(Debug, Serialize)]
63|struct ChatChoice {
64|    index: usize,
65|    message: ChatMessage,
66|    finish_reason: Option<String>,
67|}
68|
69|#[derive(Debug, Serialize)]
70|struct Usage {
71|    prompt_tokens: i32,
72|    completion_tokens: i32,
73|    total_tokens: i32,
74|}
75|
76|// Streaming chunk types
77|#[derive(Debug, Serialize)]
78|struct ChatCompletionChunk {
79|    id: String,
80|    object: String,
81|    created: i64,
82|    model: String,
83|    choices: Vec<ChatChoiceChunk>,
84|}
85|
86|#[derive(Debug, Serialize)]
87|struct ChatChoiceChunk {
88|    index: usize,
89|    delta: Option<DeltaContent>,
90|    finish_reason: Option<String>,
91|}
92|
93|#[derive(Debug, Serialize)]
94|struct DeltaContent {
95|    role: Option<String>,
96|    content: Option<String>,
97|}
98|
99|// Model management types
100|#[derive(Debug, Deserialize)]
101|struct LoadModelRequest {
102|    model_path: String,
103|    #[serde(default)]
104|    model_id: Option<String>,
105|}
106|
107|#[derive(Debug, Serialize)]
108|struct ModelStatus {
109|    id: String,
110|    path: String,
111|    loaded_at: i64,
112|    status: String,
113|}
114|
115|// ── Server state with connection pooling ────────────────────────────
116|
117|struct ModelSlot {
118|    runner: Option<LlamaRunner>,
119|    model_id: Option<String>,
120|    model_path: Option<String>,
121|}
122|
123|#[derive(Clone)]
124|struct AppState {
125|    /// Pool of model slots for concurrent request handling
126|    slots: Arc<Vec<Mutex<ModelSlot>>>,
127|    loaded_models: Arc<RwLock<std::collections::HashMap<String, String>>>, // id -> path
128|}
129|
130|impl AppState {
131|    fn new(pool_size: usize) -> Self {
132|        let mut slots = Vec::with_capacity(pool_size);
133|        for _ in 0..pool_size {
134|            slots.push(Mutex::new(ModelSlot {
135|                runner: None,
136|                model_id: None,
137|                model_path: None,
138|            }));
139|        }
140|
141|        Self {
142|            slots: Arc::new(slots),
143|            loaded_models: Arc::new(RwLock::new(std::collections::HashMap::new())),
144|        }
145|    }
146|
147|    async fn get_or_load_model(
148|        &self,
149|        model_id: &str,
150|        model_path: &str,
151|    ) -> Result<(usize, String), (StatusCode, Json<serde_json::Value>)> {
152|        // Check if already loaded
153|        let path = {
154|            let models = self.loaded_models.read().await;
155|            models.get(model_id).cloned()
156|        };
157|        
158|        if let Some(path) = path {
159|            return Ok((0, path)); // Slot 0 for simplicity
160|        }
161|
162|        // Find an empty slot and load model
163|        for (i, slot) in self.slots.iter().enumerate() {
164|            let mut s = slot.lock().await;
165|            if s.runner.is_none() {
166|                match LlamaRunner::builder(model_path).build() {
167|                    Ok(runner) => {
168|                        s.runner = Some(runner);
169|                        s.model_id = Some(model_id.to_string());
170|                        s.model_path = Some(model_path.to_string());
171|
172|                        let mut models = self.loaded_models.write().await;
173|                        models.insert(model_id.to_string(), model_path.to_string());
174|                        drop(models);
175|
176|                        tracing::info!(model = model_id, path = model_path, "Model loaded");
177|                        return Ok((i, model_path.to_string()));
178|                    }
179|                    Err(e) => {
180|                        let err = format!("Failed to load model '{}': {}", model_id, e);
181|                        return Err((StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": err}))));
182|                    }
183|                }
184|            }
185|        }
186|
187|        Err((StatusCode::SERVICE_UNAVAILABLE, Json(serde_json::json!({
188|            "error": "No available model slots"
189|        }))))
190|    }
191|
192|    async fn unload_model(&self, model_id: &str) -> Result<(), (StatusCode, Json<serde_json::Value>)> {
193|        let mut models = self.loaded_models.write().await;
194|        if !models.contains_key(model_id) {
195|            return Err((StatusCode::NOT_FOUND, Json(serde_json::json!({
196|                "error": format!("Model '{}' not loaded", model_id)
197|            }))));
198|        }
199|
200|        // Find and clear the slot
201|        for slot in self.slots.iter() {
202|            let mut s = slot.lock().await;
203|            if s.model_id.as_deref() == Some(model_id) {
204|                s.runner = None;
205|                s.model_id = None;
206|                s.model_path = None;
207|                break;
208|            }
209|        }
210|
211|        models.remove(model_id);
212|        tracing::info!(model = model_id, "Model unloaded");
213|        Ok(())
214|    }
215|}
216|
217|// ── Handlers ────────────────────────────────────────────────────────
218|
219|async fn list_models(
220|    State(app): State<AppState>,
221|) -> Json<serde_json::Value> {
222|    let models = app.loaded_models.read().await;
223|    let data: Vec<serde_json::Value> = models.keys().map(|id| {
224|        serde_json::json!({
225|            "id": id,
226|            "object": "model",
227|            "created": Utc::now().timestamp(),
228|            "owned_by": "pesti"
229|        })
230|    }).collect();
231|
232|    Json(serde_json::json!({"object": "list", "data": data}))
233|}
234|
235|async fn load_model_handler(
236|    State(app): State<AppState>,
237|    Json(req): Json<LoadModelRequest>,
238|) -> Result<Json<ModelStatus>, (StatusCode, Json<serde_json::Value>)> {
239|    let model_id = req.model_id.unwrap_or_else(|| {
240|        // Derive ID from path
241|        let filename = std::path::Path::new(&req.model_path)
242|            .file_name()
243|            .map(|f| f.to_string_lossy().to_string())
244|            .unwrap_or_else(|| "model".to_string());
245|        filename
246|    });
247|
248|    let (slot, path) = app.get_or_load_model(&model_id, &req.model_path).await?;
249|
250|    Ok(Json(ModelStatus {
251|        id: model_id,
252|        path,
253|        loaded_at: Utc::now().timestamp(),
254|        status: "loaded".to_string(),
255|    }))
256|}
257|
258|async fn unload_model_handler(
259|    State(app): State<AppState>,
260|    Json(req): Json<serde_json::Value>,
261|) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
262|    let model_id = req["model"].as_str().ok_or_else(|| {
263|        (StatusCode::BAD_REQUEST, Json(serde_json::json!({"error": "Missing 'model' field"})))
264|    })?;
265|
266|    app.unload_model(model_id).await?;
267|
268|    Ok(Json(serde_json::json!({
269|        "id": model_id,
270|        "status": "unloaded"
271|    })))
272|}
273|
274|async fn chat_completions(
275|    State(app): State<AppState>,
276|    Json(req): Json<ChatCompletionRequest>,
277|) -> Result<axum::response::Response, (StatusCode, Json<serde_json::Value>)> {
278|    let model_id = req.model.clone();
279|    let temperature = req.temperature;
280|    let top_p = req.top_p;
281|    let max_tokens = req.max_tokens;
282|    let stream = req.stream;
283|
284|    // Load or get existing model
285|    let (slot_idx, _model_path) = app.get_or_load_model(&model_id, &model_id).await?;
286|
287|    tracing::info!(slot = slot_idx, "Got model slot for chat request");
288|
289|    // Build prompt using model's chat template
290|    {
291|        let slot = &app.slots[slot_idx];
292|        let s = slot.lock().await;
293|        
294|        if let Some(runner) = &s.runner {
295|            tracing::info!("Runner found in slot, converting messages");
296|            
297|            // Convert messages to llama.cpp chat format
298|            let llama_messages: Vec<LlamaChatMessage> = req.messages.iter()
299|                .filter_map(|m| {
300|                    match LlamaChatMessage::new(m.role.clone(), m.content.clone()) {
301|                        Ok(msg) => Some(msg),
302|                        Err(e) => {
303|                            eprintln!("Failed to create chat message: {}", e);
304|                            None
305|                        }
306|                    }
307|                })
308|                .collect();
309|            
310|            tracing::info!(count = llama_messages.len(), "Converted messages, applying template");
311|            
312|            // Apply chat template (uses model's built-in template)
313|            let prompt = runner.apply_chat_template(&llama_messages, true).map_err(|e| {
314|                (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()})))
315|            })?;
316|
317|            tracing::info!(prompt_len = prompt.len(), "Template applied, calling generate");
318|
319|            if stream {
320|                // Generate response first (llama.cpp generates all at once)
321|                let sampling = SamplingConfig {
322|                    temperature,
323|                    top_p,
324|                    max_tokens,
325|                    ..Default::default()
326|                };
327|
328|                let generation_result = runner.generate(&prompt, &sampling);
329|
330|                // Now create stream with the result
331|                let id = format!("chatcmpl-{}", Uuid::new_v4().to_string().chars().take(8).collect::<String>());
332|                let created = Utc::now().timestamp();
333|                let model_id_clone = model_id.clone();
334|
335|                match generation_result {
336|                    Ok(result) => {
337|                        let stream = async_stream::stream! {
338|                            // First chunk with role
339|                            yield Ok::<_, axum::Error>(Event::default().data(serde_json::json!({
340|                                "id": format!("chatcmpl-{}", Uuid::new_v4().to_string().chars().take(8).collect::<String>()),
341|                                "object": "chat.completion.chunk",
342|                                "created": Utc::now().timestamp(),
343|                                "model": model_id_clone.clone(),
344|                                "choices": [{
345|                                    "index": 0,
346|                                    "delta": {"role": "assistant", "content": ""},
347|                                    "finish_reason": null
348|                                }]
349|                            }).to_string()));
350|
